cd /output && cat > /tmp/selftest.mjs <<'EOF'
import { sha1 } from '/output/lib/sha1.mjs';
import { hmac } from '/output/lib/hmac.mjs';
import { pbkdf2, PBKDF2 } from '/output/lib/pbkdf2.mjs';
import { utf8Encode, toHex } from '/output/lib/bytes.mjs';

const chk = (label, got, want) =>
  console.log(`${got === want ? 'PASS' : 'FAIL'}  ${label}\n      got=${got}\n      want=${want}`);

// --- SHA-1 known answers -------------------------------------------------
chk('sha1("")', toHex(sha1(utf8Encode(''))), 'da39a3ee5e6b4b0d3255bfef95601890afd80709');
chk('sha1("abc")', toHex(sha1(utf8Encode('abc'))), 'a9993e364706816aba3e25717850c26c9cd0d89d');
chk('sha1(448-bit msg)', toHex(sha1(utf8Encode('abcdbcdecdefdefgefghfghighijhijkijkljklmklmnlmnomnopnopq'))),
    '84983e441c3bd26ebaae4aa1f95129e5e54670f1');
chk('sha1("a"x1000000)', toHex(sha1(utf8Encode('a'.repeat(1000000)))),
    '34aa973cd4c4daa4f61eeb2bdbad27316534016f');
// boundary lengths 55/56/63/64
chk('sha1("a"x55)', toHex(sha1(utf8Encode('a'.repeat(55)))), 'c1c8bbdc22796e28c0e15163d20899b65621d65a');
chk('sha1("a"x56)', toHex(sha1(utf8Encode('a'.repeat(56)))), 'a7b7e9592daa0896db0517bf8ad53e56b1246923');
chk('sha1("a"x64)', toHex(sha1(utf8Encode('a'.repeat(64)))), '0098ba824b5c16427bd7a1122a5a442a25ec644d');

// --- HMAC-SHA1 (RFC 2202) ------------------------------------------------
chk('hmac case1', toHex(hmac(new Uint8Array(20).fill(0x0b), utf8Encode('Hi There'))),
    'b617318655057264e28bc0b6fb378c8ef146be00');
chk('hmac case2', toHex(hmac(utf8Encode('Jefe'), utf8Encode('what do ya want for nothing?'))),
    'effcdf6ae5eb2fa2d27416d5f184df9c259a7c79');
chk('hmac case6 (key>block)', toHex(hmac(new Uint8Array(80).fill(0xaa),
    utf8Encode('Test Using Larger Than Block-Size Key - Hash Key First'))),
    'aa4ae5e15272d00e95705637ce8a3b55ed402112');

// --- PBKDF2-HMAC-SHA1 (RFC 6070) ----------------------------------------
chk('rfc6070 c=1',    toHex(pbkdf2('password', 'salt', 20, 1)),    '0c60c80f961f0e71f3a9b524af6012062fe037a6');
chk('rfc6070 c=2',    toHex(pbkdf2('password', 'salt', 20, 2)),    'ea6c014dc72d6f8ccd1ed92ace1d41f0d8de8957');
chk('rfc6070 c=4096', toHex(pbkdf2('password', 'salt', 20, 4096)), '4b007901b765489abead49d926f721d065a429c1');
chk('rfc6070 multiblock dkLen=25', toHex(pbkdf2('passwordPASSWORDpassword','salt'+'SALT'+'saltSALTsaltSALTsaltSALTsaltSALTsalt',25,4096)),
    '3d2eec4fe41c849b80c8d83662c0e44a8b291a964cf2f07038');

// --- streaming read() semantics -----------------------------------------
const s = new PBKDF2('password', 'salt', 4096);
const a = toHex(s.read(10)), b = toHex(s.read(15));
chk('split read(10)+read(15)', a + b, '3d2eec4fe41c849b80c8'.slice(0,20) + '');
console.log('   split parts:', a, b);
const one = toHex(pbkdf2('password','salt',25,4096));
chk('split == one-shot', a + b, one);
