/**
 * cli.mjs -- a minimal, behaviour-faithful reimplementation of the subset of
 * Python's `argparse` used by the original script.
 *
 * The original builds four required string options:
 *
 *     parser.add_argument('--a', type=str, required=True)   # ... and --b --c --d
 *
 * Behaviour reproduced here, all verified against the reference build:
 *   - `--a VALUE` and `--a=VALUE` forms (the `=` form splits on the *first* `=`)
 *   - a repeated option keeps the last value
 *   - `-h` / `--help` prints help to stdout and exits 0, as soon as it is
 *     reached in the token stream
 *   - a missing value reports `argument --a: expected one argument` (exit 2);
 *     dash-prefixed tokens are refused as values *unless* they look like a
 *     negative number (`-5`, `-5.5`), matching argparse's
 *     `_negative_number_matcher`
 *   - missing required options report them in declaration order (exit 2)
 *   - leftover tokens report `unrecognized arguments: ...` joined by spaces
 *   - error precedence: missing-value > help > missing-required > unrecognized
 */

import { basename } from 'node:path';

/** Option names in declaration order -- drives usage text and error ordering. */
const OPTIONS = ['a', 'b', 'c', 'd'];

/** argparse's `_negative_number_matcher`. */
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

/**
 * Does `token` look like an option rather than a value?
 *
 * Mirrors `argparse._parse_optional()`: a lone `-`, an empty string and
 * negative-number-looking tokens are values; anything else starting with `-`
 * is an option (including the `--` separator).
 *
 * @param {string} token
 * @returns {boolean}
 */
function looksLikeOption(token) {
  if (token.length <= 1 || token[0] !== '-') return false;
  if (NEGATIVE_NUMBER.test(token)) return false;
  return true;
}

/**
 * The one-line usage string.
 *
 * @param {string} prog
 * @returns {string}
 */
function formatUsage(prog) {
  const spec = OPTIONS.map((name) => `--${name} ${name.toUpperCase()}`).join(' ');
  return `usage: ${prog} [-h] ${spec}`;
}

/**
 * The full `--help` body, matching argparse's default HelpFormatter layout
 * (help column at 14, since `-h, --help` is the longest invocation).
 *
 * @param {string} prog
 * @returns {string}
 */
function formatHelp(prog) {
  const lines = [
    formatUsage(prog),
    '',
    'options:',
    '  -h, --help  show this help message and exit',
  ];
  for (const name of OPTIONS) {
    lines.push(`  --${name} ${name.toUpperCase()}`);
  }
  return `${lines.join('\n')}\n`;
}

/**
 * Print usage plus an error message to stderr and exit with status 2, the way
 * `ArgumentParser.error()` does.
 *
 * @param {string} prog
 * @param {string} message
 * @returns {never}
 */
function fail(prog, message) {
  process.stderr.write(`${formatUsage(prog)}\n`);
  process.stderr.write(`${prog}: error: ${message}\n`);
  process.exit(2);
}

/**
 * Parse command line arguments.
 *
 * @param {string[]} [argv=process.argv] full argv, including node and script
 * @returns {{a: string, b: string, c: string, d: string}}
 */
export function parseArgs(argv = process.argv) {
  // argparse derives prog from `os.path.basename(sys.argv[0])`.
  const prog = argv[1] ? basename(argv[1]) : 'test6.mjs';
  const tokens = argv.slice(2);

  /** @type {Record<string, string>} */
  const values = {};
  /** @type {string[]} */
  const extras = [];
  let helpRequested = false;

  for (let i = 0; i < tokens.length; i++) {
    const token = tokens[i];

    if (!looksLikeOption(token)) {
      extras.push(token);
      continue;
    }

    // Split `--name=value` on the first `=` only.
    let name = token;
    let inlineValue = null;
    const eq = token.indexOf('=');
    if (eq !== -1) {
      name = token.slice(0, eq);
      inlineValue = token.slice(eq + 1);
    }

    if (name === '-h' || name === '--help') {
      helpRequested = true;
      continue;
    }

    const key = name.startsWith('--') ? name.slice(2) : null;
    if (key !== null && OPTIONS.includes(key)) {
      if (inlineValue !== null) {
        values[key] = inlineValue;
      } else if (i + 1 < tokens.length && !looksLikeOption(tokens[i + 1])) {
        values[key] = tokens[i + 1];
        i++;
      } else {
        fail(prog, `argument ${name}: expected one argument`);
      }
      continue;
    }

    // Unknown option: argparse keeps the raw token (and any trailing value
    // tokens, which fall through as unconsumed positionals).
    extras.push(token);
  }

  if (helpRequested) {
    process.stdout.write(formatHelp(prog));
    process.exit(0);
  }

  const missing = OPTIONS.filter((name) => !(name in values)).map((name) => `--${name}`);
  if (missing.length > 0) {
    fail(prog, `the following arguments are required: ${missing.join(', ')}`);
  }

  if (extras.length > 0) {
    fail(prog, `unrecognized arguments: ${extras.join(' ')}`);
  }

  return { a: values.a, b: values.b, c: values.c, d: values.d };
}

